from fastapi import FastAPI, Body, Response
from fastapi.testclient import TestClient
from typing import Annotated

app = FastAPI()

@app.get("/")
def endpoint(response: Annotated[Response, Body()]):
    return {"message": "Hello World"}

client = TestClient(app)

def test_response_body_fail():
    try:
        # This should fail during app initialization or when the endpoint is analyzed
        # In FastAPI, endpoint analysis happens when the app is created or when the route is added.
        # Since we created the app, it should have already failed if it's checked at startup.
        # However, FastAPI often analyzes parameters when the route is first called or during startup.
        # Let's try to call it.
        client.get("/")
        print("Test failed: Should have raised AssertionError")
    except AssertionError as e:
        print(f"Caught expected AssertionError: {e}")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_response_body_fail()
